const body = $input.first().json.body || $input.first().json;
const record = body.record || body;

if (!record || !record.id) {
  throw new Error('Invalid webhook payload: missing record.id');
}

const supabaseUrl = 'https://YOUR_PROJECT_ID.supabase.co';
const supabaseKey = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';

return [{
  json: {
    id: record.id,
    guest_id: record.guest_id,
    room_id: record.room_id,
    description: record.description || '',
    status: record.status || 'new',
    category: record.category || null,
    created_at: record.created_at,
    supabase_url: supabaseUrl.replace(/\/$/, ''),
    supabase_key: supabaseKey
  }
}];

const orig = $node["Validate Webhook Payload"].json;
const description = orig.description || '';
const lower = description.toLowerCase();

let rawText = '';
try {
  const inputData = $input.first().json;
  rawText = inputData.text || inputData.response || inputData.output || JSON.stringify(inputData);
} catch (e) {
  rawText = '';
}
rawText = String(rawText).replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();

let parsed = {};
try {
  const match = rawText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : rawText);
} catch (err) {
  parsed = {};
}
if (!parsed || typeof parsed !== 'object') {
  parsed = {};
}

const validCategories = ['housekeeping', 'maintenance', 'room_service', 'complaint', 'other'];
const validPriorities = ['low', 'normal', 'high', 'urgent'];
const validSentiments = ['positive', 'neutral', 'negative'];

const keywordCategories = {
  maintenance: ['ac ', 'a/c', 'air condition', 'plumbing', 'toilet', 'shower', 'leak', 'broken', 'not working', 'electric', 'power', 'light', 'tv', 'heater', 'تكييف', 'مكيف', 'سباك', 'تسريب', 'كهرباء', 'عطل', 'مكسور', 'لا يعمل'],
  housekeeping: ['clean', 'towel', 'linen', 'sheet', 'pillow', 'blanket', 'soap', 'shampoo', 'amenit', 'تنظيف', 'نظافة', 'منشفة', 'مناشف', 'ملاءة', 'ملايات', 'وسادة', 'بطانية'],
  room_service: ['food', 'meal', 'breakfast', 'lunch', 'dinner', 'drink', 'coffee', 'water bottle', 'menu', 'order', 'طعام', 'أكل', 'اكل', 'مشروب', 'فطار', 'غداء', 'عشاء', 'قهوة'],
  complaint: ['complain', 'unacceptable', 'terrible', 'awful', 'worst', 'disappointed', 'angry', 'rude', 'noisy', 'dirty', 'شكوى', 'سيء', 'سيئ', 'مستاء', 'غاضب', 'مزعج', 'قذر']
};

let category = String(parsed.category || '').toLowerCase().trim();
let priority = String(parsed.priority || '').toLowerCase().trim();
let summary = parsed.summary ? String(parsed.summary).trim() : '';
let sentiment = parsed.sentiment ? String(parsed.sentiment).toLowerCase().trim() : null;

if (!validCategories.includes(category)) {
  category = 'other';
  for (const [name, words] of Object.entries(keywordCategories)) {
    if (words.some(w => lower.includes(w))) {
      category = name;
      break;
    }
  }
}
if (!validPriorities.includes(priority)) {
  priority = 'normal';
}
if (!summary) {
  summary = description.trim().slice(0, 200) || 'Guest request processed.';
}

const urgentKeywords = [
  'leak', 'leaking', 'flood', 'flooding', 'fire', 'smoke', 'spark', 'electric',
  'lockout', 'locked out', 'no power', 'no electricity', 'danger', 'hazard',
  'تسريب', 'حريق', 'دخان', 'كهرباء', 'ماس', 'محبوس', 'غرق'
];
if (urgentKeywords.some(kw => lower.includes(kw))) {
  priority = 'urgent';
}

if (category === 'complaint') {
  if (priority === 'low') {
    priority = 'normal';
  }
  if (!validSentiments.includes(sentiment)) {
    sentiment = 'negative';
  }
} else {
  sentiment = null;
}

return [{
  json: {
    id: orig.id,
    category,
    priority,
    ai_summary: summary,
    sentiment,
    status: 'classified',
    supabase_url: orig.supabase_url,
    supabase_key: orig.supabase_key
  }
}];
